WITH ranked AS (
  SELECT *, ROW_NUMBER() OVER (
      PARTITION BY order_id ORDER BY loaded_at DESC
  ) AS rn
  FROM raw.orders
)
SELECT * FROM ranked WHERE rn = 1;

SELECT order_id, customer_id, order_total, loaded_at
FROM raw.orders
QUALIFY ROW_NUMBER() OVER (
    PARTITION BY order_id ORDER BY loaded_at DESC
) = 1;
